import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { Field as BaseField } from "@base-ui/react/field";
import { cn } from "@/lib/utils";

const elevatedSurfaceClass = cn(
  "relative isolate overflow-hidden rounded-[var(--primitive-radius-surface)]",
  "border border-[var(--border)] bg-[var(--primitive-surface-elevated)]",
  "[box-shadow:var(--primitive-shadow-raised)]",
);

export type FormFieldLayout = "stack" | "inline" | "split" | "card";
export type FormFieldDensity = "sm" | "md" | "lg";

export interface FormFieldProps extends React.HTMLAttributes<HTMLDivElement> {
  id?: string;
  label?: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  optional?: boolean;
  layout?: FormFieldLayout;
  density?: FormFieldDensity;
  children: React.ReactNode;
  labelClassName?: string;
  descriptionClassName?: string;
  errorClassName?: string;
}

export interface FormFieldContextValue {
  controlId: string;
  descriptionId?: string;
  errorId?: string;
  describedBy?: string;
  invalid: boolean;
  required?: boolean;
}

export interface FormFieldControlProps
  extends React.HTMLAttributes<HTMLElement> {
  asChild?: boolean;
}

export interface FormFieldLabelProps
  extends React.LabelHTMLAttributes<HTMLLabelElement> {
  required?: boolean;
  optional?: boolean;
}

export interface FormFieldDescriptionProps
  extends React.HTMLAttributes<HTMLParagraphElement> {}

export interface FormFieldErrorProps
  extends React.HTMLAttributes<HTMLParagraphElement> {}

export interface FormSectionProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  title?: React.ReactNode;
  description?: React.ReactNode;
  actions?: React.ReactNode;
  divided?: boolean;
}

export interface FormActionsProps extends React.HTMLAttributes<HTMLDivElement> {
  align?: "left" | "right" | "between";
}

const FormFieldContext = React.createContext<FormFieldContextValue | null>(
  null,
);

const layoutClasses: Record<FormFieldLayout, string> = {
  stack: "flex flex-col",
  inline:
    "grid items-start gap-x-5 sm:grid-cols-[minmax(8rem,0.42fr)_minmax(0,1fr)]",
  split:
    "grid items-start gap-x-6 sm:grid-cols-[minmax(10rem,0.5fr)_minmax(0,1fr)]",
  card: elevatedSurfaceClass,
};

const densityGap: Record<FormFieldDensity, string> = {
  sm: "gap-1.5",
  md: "gap-1.5",
  lg: "gap-2.5",
};

const cardPadding: Record<FormFieldDensity, string> = {
  sm: "p-3.5",
  md: "p-4",
  lg: "p-5",
};

const labelTextClass =
  "block text-[13px] font-medium leading-none tracking-[-0.01em] text-[var(--foreground)]";

const helperTextClass =
  "text-[12px] leading-[1.45] text-[var(--primitive-text-secondary)]";

const errorTextClass =
  "text-[12px] leading-[1.45] font-medium text-[var(--primitive-destructive)] motion-safe:transition-[opacity,transform] motion-safe:duration-150 motion-safe:ease-[var(--primitive-ease)] motion-reduce:transition-none";

function useFormFieldContext(component: string) {
  const context = React.useContext(FormFieldContext);
  if (!context) {
    throw new Error(`${component} must be used inside FormField.`);
  }
  return context;
}

function FieldLabelMarker({
  required,
  optional,
}: {
  required?: boolean;
  optional?: boolean;
}) {
  if (required) {
    return (
      <span
        aria-hidden="true"
        className="ml-1 font-medium text-[var(--primitive-destructive)]"
      >
        *
      </span>
    );
  }

  if (optional) {
    return (
      <span
        role="note"
        className="ml-2 text-[length:var(--primitive-text-hint)] font-medium text-[var(--primitive-text-secondary)]"
      >
        Optional
      </span>
    );
  }

  return null;
}

export function FormField({
  id,
  label,
  description,
  error,
  required,
  optional,
  layout = "stack",
  density = "md",
  children,
  className,
  labelClassName,
  descriptionClassName,
  errorClassName,
  ...props
}: FormFieldProps) {
  const reactId = React.useId();
  const controlId = id ?? `wensity-field-${reactId}`;
  const descriptionId = description ? `${controlId}-description` : undefined;
  const errorId = error ? `${controlId}-error` : undefined;
  const describedBy =
    [errorId, descriptionId].filter(Boolean).join(" ") || undefined;

  const context = React.useMemo<FormFieldContextValue>(
    () => ({
      controlId,
      descriptionId,
      errorId,
      describedBy,
      invalid: Boolean(error),
      required,
    }),
    [controlId, describedBy, descriptionId, errorId, error, required],
  );

  const meta =
    label || description ? (
      <div className={cn("min-w-0", layout !== "stack" && "pt-1")}>
        {label ? (
          <FormFieldLabel
            required={required}
            optional={optional}
            className={labelClassName}
          >
            {label}
          </FormFieldLabel>
        ) : null}
        {description ? (
          <FormFieldDescription className={cn("mt-1", descriptionClassName)}>
            {description}
          </FormFieldDescription>
        ) : null}
      </div>
    ) : null;

  const control = (
    <div className="min-w-0">
      {children}
      {error ? (
        <FormFieldError className={cn("mt-1", errorClassName)}>
          {error}
        </FormFieldError>
      ) : null}
    </div>
  );

  return (
    <FormFieldContext.Provider value={context}>
      <BaseField.Root data-wensity-primitive=""
        invalid={Boolean(error)}
        data-slot="form-field"
        data-layout={layout}
        data-invalid={error ? "" : undefined}
        className={cn(
          layoutClasses[layout],
          densityGap[density],
          layout === "card" && cardPadding[density],
          className,
        )}
        {...props}
      >
        {meta}
        {control}
      </BaseField.Root>
    </FormFieldContext.Provider>
  );
}

export function FormFieldControl({
  asChild = false,
  className,
  children,
  ...props
}: FormFieldControlProps) {
  const context = useFormFieldContext("FormFieldControl");

  if (asChild && React.isValidElement(children)) {
    // Pass the child element as `render` so Base UI runs mergeProps(controlProps, child.props):
    // child props win and event handlers compose (Radix Slot semantics).
    return (
      <BaseField.Control
        id={context.controlId}
        className={className}
        aria-describedby={context.describedBy}
        aria-invalid={context.invalid || undefined}
        aria-required={context.required || undefined}
        render={children}
        {...props}
      />
    );
  }

  return (
    <BaseField.Control
      id={context.controlId}
      render={(controlProps) => (
        <div
          {...controlProps}
          aria-describedby={
            (controlProps["aria-describedby"] as string | undefined) ??
            context.describedBy
          }
          aria-invalid={context.invalid || undefined}
          aria-required={context.required || undefined}
          className={cn(controlProps.className as string | undefined, className)}
          {...props}
        >
          {children}
        </div>
      )}
    />
  );
}

export function FormFieldLabel({
  required,
  optional,
  className,
  children,
  ...props
}: FormFieldLabelProps) {
  const context = useFormFieldContext("FormFieldLabel");

  return (
    <BaseField.Label className={cn(labelTextClass, className)} {...props}>
      {children}
      <FieldLabelMarker
        required={required ?? context.required}
        optional={optional}
      />
    </BaseField.Label>
  );
}

export function FormFieldDescription({
  className,
  ...props
}: FormFieldDescriptionProps) {
  const context = useFormFieldContext("FormFieldDescription");

  return (
    <BaseField.Description
      id={context.descriptionId}
      className={cn(helperTextClass, className)}
      {...props}
    />
  );
}

export function FormFieldError({ className, ...props }: FormFieldErrorProps) {
  const context = useFormFieldContext("FormFieldError");

  return (
    <BaseField.Error
      id={context.errorId}
      match
      role="alert"
      className={cn(errorTextClass, className)}
      {...props}
    />
  );
}

export function FormSection({
  title,
  description,
  actions,
  divided = false,
  children,
  className,
  ...props
}: FormSectionProps) {
  return (
    <section className={cn(elevatedSurfaceClass, className)} {...props}>
      {title || description || actions ? (
        <header className="flex items-start justify-between gap-4 border-b border-[var(--border)] px-5 py-4">
          <div className="min-w-0">
            {title ? (
              <h3 className="font-[family-name:var(--primitive-font-display)] text-sm font-semibold tracking-[-0.015em] text-[var(--foreground)]">
                {title}
              </h3>
            ) : null}
            {description ? (
              <p className={cn("mt-1", helperTextClass)}>{description}</p>
            ) : null}
          </div>
          {actions ? <div className="shrink-0">{actions}</div> : null}
        </header>
      ) : null}
      <div
        className={cn(
          "p-5",
          divided &&
            "[&>[data-slot=form-field]]:border-b [&>[data-slot=form-field]]:border-[var(--border)] [&>[data-slot=form-field]]:py-4 [&>[data-slot=form-field]:first-child]:pt-0 [&>[data-slot=form-field]:last-child]:border-b-0 [&>[data-slot=form-field]:last-child]:pb-0",
          !divided && "space-y-4",
        )}
      >
        {children}
      </div>
    </section>
  );
}

export function FormActions({
  align = "right",
  className,
  ...props
}: FormActionsProps) {
  return (
    <div
      className={cn(
        "flex flex-wrap items-center gap-2",
        align === "left" && "justify-start",
        align === "right" && "justify-end",
        align === "between" && "justify-between",
        className,
      )}
      {...props}
    />
  );
}
